mapper.select:
SELECT
,(select empname from comm_employee where badge = pro_manager and ISDISABLED = '0' and rownum =1) as proManagerName FROM PPM_PAYMENT_CONFIRM where id in
#{ids}

SELECT contract_no, contract_name, outsource_no, tax_rate, SUM(actual_price) amount_raw FROM (SELECT a.contract_no, a.contract_name, b.outsource_no, b.price * (c.actual_attendance_days / c.required_attendance_days) actual_price, tax_rate FROM (SELECT id,contract_no, contract_name, tax_rate FROM PPM_VENDOR_CONTRACT WHERE IS_DEL = '0') a LEFT JOIN (SELECT JOB_ID, outsource_no, user_name, PERSON_IN_CHARGE, price, NEW_CONTRACT_ID as contract_id FROM PPM_OUTSOURCING_BASIC
) b ON a.id = b.contract_id LEFT JOIN PPM_KQ_INFO c ON b.job_id = c.job_id WHERE a.CONTRACT_NO = #{contractNo} AND PERSON_IN_CHARGE = #{proManager}
) GROUP BY contract_no, contract_name, outsource_no, tax_rate

SELECT JOB_ID as jobId ,USER_NAME as userName ,substr(ATTENDANCE_DATE,0,4) as paymentYear ,substr(ATTENDANCE_DATE,5,5) as paymentMonth ,max(REQUIRED_ATTENDANCE_DAYS) as requiredAttendanceDays ,max(ACTUAL_ATTENDANCE_DAYS) as actualAttendanceDays ,round(sum(price),2) as actualPrice ,max(prices) as price FROM ( SELECT pki.id ,t.JOB_ID ,t.USER_NAME ,t.ATTENDANCE_DATE ,prices ,case t.am_whether_abnormal + t.pm_whether_abnormal when 2 then 0 when 1 then 1/2*1/pki.required_attendance_days*t.prices else 1/pki.required_attendance_days*t.prices end price ,pki.REQUIRED_ATTENDANCE_DAYS ,pki.ACTUAL_ATTENDANCE_DAYS ,new_contract_id FROM ( SELECT pkr.JOB_ID,pkr.user_name, pkr.am_whether_abnormal ,pkr.pm_whether_abnormal ,pkr.is_holiday ,pkr.outsource_type ,TO_CHAR(pkr.ATTENDANCE_DATE,'yyyyMM') AS ATTENDANCE_DATE ,pkr.prices ,pob.person_in_charge ,pob.new_contract_id FROM PPM_KQ_RECORD pkr LEFT JOIN PPM_OUTSOURCING_BASIC pob ON pkr.job_id = pob.job_id ) t LEFT JOIN PPM_KQ_INFO pki on t.job_id = pki.job_id WHERE pki.attendance_month = t.attendance_date AND t.attendance_date >= #{feeStartDate} AND t.attendance_date <= #{feeEndDate} AND t.job_id in
#{jobId}
AND is_holiday = '0' and outsource_type = '1' ) group by JOB_ID,USER_NAME,ATTENDANCE_DATE ORDER BY JOB_ID,ATTENDANCE_DATE

SELECT JOB_ID as jobId, USER_NAME as userName, substr(ATTENDANCE_DATE, 0, 4) as paymentYear, substr(ATTENDANCE_DATE, 5, 5) as paymentMonth, round(sum(price), 2) as actualPrice, (select sum(day) tt from (select case kqr.am_whether_abnormal + kqr.pm_whether_abnormal when 2 then 0 when 1 then 0.5 else 1 END day, job_id from PPM_KQ_RECORD kqr where attendance_date >= to_date(#{feeStartDate}, 'yyyyMMdd') and attendance_date <= to_date(#{feeEndDate}, 'yyyyMMdd') and is_holiday = '0') t1 where t1.job_id = st.JOB_ID) as actualAttendanceDayst, (select count(1) from PPM_KQ_RECORD kqr where attendance_date >= to_date(#{feeStartDate}, 'yyyyMMdd') and attendance_date <= to_date(#{feeEndDate}, 'yyyyMMdd') and is_holiday = '0' and kqr.job_id = st.JOB_ID) as requiredAttendanceDayst, max(REQUIRED_ATTENDANCE_DAYS) as requiredAttendanceDaysq, max(ACTUAL_ATTENDANCE_DAYS) as actualAttendanceDaysq, max(prices) as price FROM (SELECT pki.id, t.JOB_ID, t.USER_NAME, substr(t.ATTENDANCE_DATE, 0, 6) as ATTENDANCE_DATE, prices, case t.am_whether_abnormal + t.pm_whether_abnormal when 2 then 0 when 1 then 1 / 2 * 1 / pki.required_attendance_days * t.prices else 1 / pki.required_attendance_days * t.prices end price, pki.REQUIRED_ATTENDANCE_DAYS, pki.ACTUAL_ATTENDANCE_DAYS, new_contract_id FROM (SELECT pkr.JOB_ID, pkr.user_name, pkr.am_whether_abnormal, pkr.pm_whether_abnormal, pkr.is_holiday, pkr.outsource_type, TO_CHAR(pkr.ATTENDANCE_DATE, 'yyyyMMdd') AS ATTENDANCE_DATE, pkr.prices, pob.person_in_charge, pob.new_contract_id FROM PPM_KQ_RECORD pkr LEFT JOIN PPM_OUTSOURCING_BASIC pob ON pkr.job_id = pob.job_id) t LEFT JOIN PPM_KQ_INFO pki on t.job_id = pki.job_id WHERE pki.attendance_month = substr(t.attendance_date, 0, 6) AND t.attendance_date >= #{feeStartDate} AND t.attendance_date <= #{feeEndDate} AND t.job_id in
#{jobId}
AND is_holiday = '0' and outsource_type = '1' ) st group by JOB_ID, USER_NAME, ATTENDANCE_DATE ORDER BY JOB_ID, ATTENDANCE_DATE

SELECT job_id as jobId, userName, to_char(attendance_date,'yyyy-MM-dd') as attendanceDate, (am_day + pm_day)||'' as actualAttendanceDays, '1' as requiredAttendanceDays FROM (SELECT a.job_id, a.user_name as userName, b.attendance_date, case when am_whether_abnormal = '0' then 0.5 else 0 end am_day, case when pm_whether_abnormal = '0' then 0.5 else 0 end pm_day FROM ( SELECT job_id, outsource_no, user_name, PERSON_IN_CHARGE, price, NEW_CONTRACT_ID as contract_id FROM PPM_OUTSOURCING_BASIC
) a LEFT JOIN PPM_KQ_RECORD b on a.job_id = b.job_id WHERE b.job_id in
#{jobId}
AND b.is_holiday = '0' AND attendance_date >= to_date(#{feeStartDate}, 'yyyyMMdd') AND attendance_date <= to_date(#{feeEndDate}, 'yyyyMMdd') ) c order by c.job_id, c.attendance_date

