INSERT INTO PPM_PAYMENT_CONFIRM (
ID , INSTANCE_ID , FLOW_ID , CONTRACT_NO , CONTRACT_NAME , VENDOR , PAYMENT_SUBMIT_DATE , FEE_START_DATE , FEE_END_DATE , APPROVAL_STATUS , IS_DEL , PRO_MANAGER , AMOUNT_RAW , AMOUNT_SALT , AMOUNT , AMOUNT_TAX , TAX_RATE , REMARK , CREATE_USER , UPDATE_USER ,
) VALUES(
#{id} , #{instanceId} , #{flowId} , #{contractNo} , #{contractName} , #{vendor} , #{paymentSubmitDate} , #{feeStartDate} , #{feeEndDate} , #{approvalStatus} , #{isDel} , #{proManager} , #{amountRaw} , #{amountSalt} , #{amount} , #{amountTax} , #{taxRate} , #{remark} , #{createUser} , #{updateUser} ,
)

