SELECT COUNT(1)
FROM PPM_PAYMENT_CONFIRM
WHERE CONTRACT_NO = #{contractNo}
AND VENDOR = #{vendor}
AND PRO_MANAGER =  #{proManager}
AND ((fee_start_date >= #{feeStartDate} and fee_start_date <= #{feeEndDate}) or (fee_end_date >= #{feeStartDate} and fee_end_date <= #{feeEndDate})
or (fee_start_date > #{feeStartDate} and #{feeEndDate} > fee_end_date))
AND is_del = '0'

SELECT

FROM PPM_PAYMENT_CONFIRM
WHERE APPROVAL_STATUS != #{approvalStatus}
AND IS_DEL = #{isDel}
AND PRO_MANAGER = #{proManager}
